package net.thunderbird.piisafe.compiler.testing

import com.tschuchort.compiletesting.JvmCompilationResult
import org.jetbrains.kotlin.compiler.plugin.ExperimentalCompilerApi

/**
 * Reflection helpers for exercising classes generated by a [JvmCompilationResult] at runtime.
 */
@OptIn(ExperimentalCompilerApi::class)
internal fun JvmCompilationResult.loadClass(name: String): Class<*> = classLoader.loadClass(name)

/**
 * Instantiates this class via its sole constructor, matching by argument count only. This avoids
 * having to look up and pass declared parameter types (e.g. an interface a constructor argument is
 * typed as), which the raw `getDeclaredConstructor(...)` API requires.
 */
internal fun Class<*>.construct(vararg args: Any?): Any =
    declaredConstructors
        .single { it.parameterCount == args.size }
        .apply { isAccessible = true }
        .newInstance(*args)

/**
 * Invokes the single public instance method named [name] with [args], matched by name and argument
 * count only.
 */
internal fun <T> Any.call(name: String, vararg args: Any?): T {
    @Suppress("UNCHECKED_CAST")
    return javaClass.methods
        .single { it.name == name && it.parameterCount == args.size }
        .apply { isAccessible = true }
        .invoke(this, *args) as T
}

/**
 * Invokes the single public static method named [name] with [args], matched by name and argument
 * count only. Used for top-level Kotlin functions, which compile to static methods on a synthetic
 * `<FileName>Kt` class.
 */
internal fun <T> Class<*>.callStatic(name: String, vararg args: Any?): T {
    @Suppress("UNCHECKED_CAST")
    return methods
        .single { it.name == name && it.parameterCount == args.size }
        .apply { isAccessible = true }
        .invoke(null, *args) as T
}

/** Reads the `captured` property most `FakeLogger` fixtures in this suite expose. */
internal fun Any.captured(): String? = call("getCaptured")
